/**
 * IntentNav-SCFR: 6-Class Witness Evidence Strict Validator
 *
 * Performs standalone, deterministic verification of the empirical evidence
 * generated by real Chromium execution for Patent Claim 8:
 * (evidence/chromium_witness_class_evidence.json)
 *
 * Enforces strict criteria:
 * 1. File existence & valid JSON syntax
 * 2. Complete schema coverage
 * 3. 100% demonstration of all 6 declared witness classes:
 *    - W1: DOM_MUTATION
 *    - W2: ACCESSIBILITY_STATE_MUTATION
 *    - W3: HISTORY_STATE_MUTATION
 *    - W4: CLIENT_ROUTE_MUTATION
 *    - W5: APPLICATION_STATE_MUTATION
 *    - W6: ASYNC_ACKNOWLEDGEMENT
 * 4. Zero classes marked NOT_YET_DEMONSTRATED
 * 5. Causal Quorum (>= 2 distinct witness classes) verified for every action
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '..');

const EVIDENCE_FILE = path.join(ROOT, 'evidence', 'chromium_witness_class_evidence.json');

const REQUIRED_ROOT_FIELDS = [
  'runId',
  'timestamp',
  'browserExecutable',
  'browserVersion',
  'environment',
  'runnerType',
  'claimReference',
  'assertions',
  'witnessClassesSummary',
  'executedScenarios',
  'rawObservationsPerClass',
];

const ALL_6_CLASSES = [
  'DOM_MUTATION',
  'ACCESSIBILITY_STATE_MUTATION',
  'HISTORY_STATE_MUTATION',
  'CLIENT_ROUTE_MUTATION',
  'APPLICATION_STATE_MUTATION',
  'ASYNC_ACKNOWLEDGEMENT',
];

function validate() {
  console.log('================================================================');
  console.log('IntentNav-SCFR: Empirical 6-Class Witness Strict Validator');
  console.log('Validating evidence/chromium_witness_class_evidence.json (Claim 8)');
  console.log('================================================================\n');

  if (!fs.existsSync(EVIDENCE_FILE)) {
    console.error(`✕ Error: Evidence file not found at ${EVIDENCE_FILE}`);
    process.exit(1);
  }

  let data;
  try {
    const raw = fs.readFileSync(EVIDENCE_FILE, 'utf8');
    data = JSON.parse(raw);
  } catch (err) {
    console.error(`✕ Error parsing evidence JSON: ${err.message}`);
    process.exit(1);
  }

  const errors = [];

  // Check 1: Root fields
  for (const field of REQUIRED_ROOT_FIELDS) {
    if (data[field] === undefined || data[field] === null) {
      errors.push(`Missing root field: ${field}`);
    }
  }

  // Check 2: Assertions
  if (data.assertions && typeof data.assertions === 'object') {
    const a = data.assertions;
    if (a.totalDeclaredClasses !== 6) errors.push(`totalDeclaredClasses must be 6, got ${a.totalDeclaredClasses}`);
    if (a.totalDemonstratedClasses !== 6) errors.push(`totalDemonstratedClasses must be 6, got ${a.totalDemonstratedClasses}`);
    if (a.all6ClassesDemonstratedInChromium !== true) errors.push('all6ClassesDemonstratedInChromium must be true');
    if (a.causalQuorumSatisfiedAcrossAllScenarios !== true) errors.push('causalQuorumSatisfiedAcrossAllScenarios must be true');
    if (a.zeroInjectedOrSyntheticWitnesses !== true) errors.push('zeroInjectedOrSyntheticWitnesses must be true');
  } else {
    errors.push('Root field "assertions" is not an object');
  }

  // Check 3: All 6 classes verified in summary
  if (data.witnessClassesSummary && typeof data.witnessClassesSummary === 'object') {
    for (const cls of ALL_6_CLASSES) {
      const info = data.witnessClassesSummary[cls];
      if (!info) {
        errors.push(`Missing witness class in summary: ${cls}`);
      } else {
        if (info.status !== 'REAL_CHROMIUM_DEMONSTRATED') {
          errors.push(`Class ${cls} status is "${info.status}"; expected "REAL_CHROMIUM_DEMONSTRATED"`);
        }
        if (typeof info.totalObservations !== 'number' || info.totalObservations <= 0) {
          errors.push(`Class ${cls} has non-positive observation count: ${info.totalObservations}`);
        }
        if (!Array.isArray(info.scenariosObservedIn) || info.scenariosObservedIn.length === 0) {
          errors.push(`Class ${cls} has no recorded scenarios in scenariosObservedIn`);
        }
      }
    }
  } else {
    errors.push('Root field "witnessClassesSummary" is not an object');
  }

  // Check 4: Quorum across all executed scenarios
  if (Array.isArray(data.executedScenarios)) {
    if (data.executedScenarios.length === 0) {
      errors.push('No scenarios recorded in executedScenarios');
    }
    data.executedScenarios.forEach((sc, idx) => {
      if (!sc.quorumSatisfied) {
        errors.push(`Scenario #${idx} (${sc.scenarioId}) failed causal quorum check`);
      }
      if (!Array.isArray(sc.witnessClasses) || sc.witnessClasses.length < 2) {
        errors.push(`Scenario #${idx} (${sc.scenarioId}) has fewer than 2 distinct witness classes: ${sc.witnessClasses}`);
      }
      if (sc.machineState !== 'EXECUTED') {
        errors.push(`Scenario #${idx} (${sc.scenarioId}) machineState is "${sc.machineState}"; expected "EXECUTED"`);
      }
    });
  } else {
    errors.push('Root field "executedScenarios" must be an array');
  }

  // Check 5: Raw observations completeness
  if (data.rawObservationsPerClass && typeof data.rawObservationsPerClass === 'object') {
    for (const cls of ALL_6_CLASSES) {
      const obs = data.rawObservationsPerClass[cls];
      if (!Array.isArray(obs) || obs.length === 0) {
        errors.push(`No raw observations found for class ${cls}`);
      }
    }
  } else {
    errors.push('Root field "rawObservationsPerClass" is not an object');
  }

  if (errors.length > 0) {
    console.error(`✕ Validation FAILED with ${errors.length} error(s):`);
    errors.forEach((err) => console.error(`  - ${err}`));
    process.exit(1);
  }

  console.log('✓ Validation PASSED: 100% of Claim 8 multi-class witness criteria satisfied.');
  console.log('  All 6 declared witness classes empirically demonstrated in real Chromium:');
  ALL_6_CLASSES.forEach((cls) => {
    const info = data.witnessClassesSummary[cls];
    console.log(`    - ${cls.padEnd(30)}: ${info.totalObservations} live observations (Scenarios: ${info.scenariosObservedIn.join(', ')})`);
  });
  console.log(`  - Causal Quorum (>=2 classes):   100% satisfied across all ${data.executedScenarios.length} scenarios`);
  console.log('  - Injected / Synthetic Bypass:   NONE (Zero)');
  console.log('\nEmpirical evidence for Patent Claim 8 is strictly verified.\n');
}

validate();
